    >
      <StackLayout gap={0}>
        <CalendarNavigation />
        <CalendarGrid />
        <Divider />
        <Button
          aria-label={`Today, ${dateAdapter.format(today, "dddd DD MMMM YYYY")}`}
          style={{ margin: "var(--salt-spacing-100)" }}
          sentiment="accented"
          appearance="solid"
          onClick={() => {
            setSelectedDate(today);
            announce(
              `${dateAdapter.format(today, "dddd DD MMMM YYYY")}, selected`,
            );
          }}
        >
          Today
        </Button>
      </StackLayout>
    </Calendar>
  );
