  useEffect(() => {
    const handleSlideChange = (emblaApi: EmblaCarouselType) => {
      const settledSlideIndex = emblaApi?.selectedScrollSnap() ?? 0;
      setSlideIndex(settledSlideIndex + 1);
    };

    if (!emblaApi || !emblaApi.plugins()?.autoplay) {
      return;
    }
    emblaApi.on("select", handleSlideChange);
    return () => {
      emblaApi.off("select", handleSlideChange);
    };
  }, [emblaApi]);

  useEffect(() => {
    if (!emblaApi) {
      return;
    }

    const handleAutoplayStop = () => {
      setPlayState((prev) => (prev === "play" ? "pause" : prev));
    };

    const handleAutoplayPlay = () => {
      setPlayState("play");
    };

    emblaApi.on("autoplay:stop", handleAutoplayStop);
    emblaApi.on("autoplay:play", handleAutoplayPlay);

    return () => {
      emblaApi.off("autoplay:stop", handleAutoplayStop);
      emblaApi.off("autoplay:play", handleAutoplayPlay);
    };
  }, [emblaApi]);

  const timeUntilNext = autoplay?.timeUntilNext() ?? DELAY_MSECS;

  const handlePointerDown = () => {
    stop();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "Tab") {
      stop();
    }
  };

  const handleMouseEnter = () => {
    if (!manualControlRef.current && playState === "play") {
      pause();
    }
  };

  const handleMouseLeave = () => {
    if (!manualControlRef.current && playState === "pause") {
      play();
    }
  };

  const handleFocus = () => {
    if (!manualControlRef.current && playState === "play") {
      pause();
    }
  };

  const handleBlur = () => {
    if (!manualControlRef.current && playState === "pause") {
      play();
    }
  };

  const togglePlayState = () => {
    manualControlRef.current = true; // Once a user interaction occurs, then autoplay is furthermore disabled
    if (playState === "play") {
      stop();
    } else {
      play();
    }
  };

  return (
    <Carousel
      aria-labelledby={`${carouselId}-title`}
      className={styles.carousel}
      disableSlideAnnouncements={playState === "play"}
      emblaOptions={{ loop: true, duration: 20 }}
      emblaPlugins={[
        AutoplayPlugin({
          delay: DELAY_MSECS,
          playOnInit: true,
        }),
        Classnames({
          snapped: styles.carouselSlideIsSnapped,
        }),
      ]}
      getEmblaApi={setEmblaApi}
      onBlur={handleBlur}
      onFocus={handleFocus}
    >
      <H2 id={`${carouselId}-title`}>Autoplay example</H2>
      <StackLayout gap={1} direction="column-reverse">
        <FlexLayout justify="start" direction="row" gap={1}>
          <Button
            aria-label={`${playState === "play" ? "stop" : "start"} automatic slide rotation`}
            appearance="bordered"
            sentiment="neutral"
            onPointerDown={() => {
              manualControlRef.current = true;
            }}
            onKeyDown={(event) => {
              if (event.key === "space") {
                manualControlRef.current = true;
              }
            }}
            onClick={togglePlayState}
          >
            {playState === "play" ? (
              <PauseSolidIcon style={{ pointerEvents: "none" }} aria-hidden />
            ) : (
              <PlaySolidIcon style={{ pointerEvents: "none" }} aria-hidden />
            )}
          </Button>
          <CarouselPreviousButton onClick={stop} />
          <CarouselNextButton onClick={stop} />
          <CarouselProgressLabel aria-hidden={true} />
          <CarouselAutoplayIndicator
            slideIndex={slideIndex}
            duration={timeUntilNext ? timeUntilNext : DELAY_MSECS}
            isPlaying={playState === "play"}
          />
        </FlexLayout>
        <CarouselSlides
          onFocus={handleFocus}
          onKeyDown={handleKeyDown}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          onPointerDown={handlePointerDown}
        >
          {sliderData.map((slide, index) => {
            const slideId = `${carouselId}-slide${index}`;
            return (
              <CarouselCard
                appearance="bordered"
                className={styles.carouselSlide}
                key={slideId}
                aria-labelledby={`${slideId}-title`}
                media={
                  <img
                    aria-hidden={true}
                    alt=""
                    className={styles.carouselImage}
                    src={slide.image}
                  />
                }
                header={<H3 id={`${slideId}-title`}>{slide.title}</H3>}
                actions={
                  <Link tabIndex={0} href="#">
                    Usage examples
                  </Link>
                }
              >
                <Text>{slide.content}</Text>
              </CarouselCard>
            );
          })}
        </CarouselSlides>
      </StackLayout>
    </Carousel>
  );
};

import {
  Button,
  FlexLayout,
  H2,
  H3,
  StackLayout,
  Text,
  useId,
} from "@salt-ds/core";
import {
  Carousel,
  CarouselCard,
  type CarouselEmblaApiType,
  CarouselNextButton,
  CarouselPreviousButton,
  CarouselProgressLabel,
  CarouselSlides,
  CarouselTabList,
} from "@salt-ds/embla-carousel";
import { type ReactElement, useEffect, useState } from "react";
import { sliderData } from "./exampleData";
import styles from "./index.module.css";

export const ControlledCarousel = (): ReactElement => {
  const [emblaApi, setEmblaApi] = useState<CarouselEmblaApiType | null>(null);

  const carouselId = useId();

  useEffect(() => {
    if (!emblaApi) {
      return;
    }

    const logSnappedSlide = () => {
      const snappedSlideIndex = emblaApi.selectedScrollSnap();
      console.log(
        `Slide ${snappedSlideIndex !== undefined ? snappedSlideIndex + 1 : undefined} is snapped into view.`,
      );
    };

    emblaApi.on("select", logSnappedSlide);

    // Cleanup listener on component unmount
    return () => {
      emblaApi.off("select", logSnappedSlide);
    };
  }, [emblaApi]);

  return (
    <>
      <Button style={{ width: "150px" }} onClick={() => emblaApi?.scrollTo(2)}>
        Scroll to slide 3
      </Button>
      <Carousel
        aria-label="Controlled carousel example"
        className={styles.carousel}
        getEmblaApi={setEmblaApi}
      >
        <H2 id={`${carouselId}-title`}>Controlled carousel example</H2>
        <StackLayout gap={1} direction="column-reverse">
          <FlexLayout gap={1} wrap={true}>
            <CarouselPreviousButton tabIndex={-1} />
            <CarouselTabList />
            <CarouselNextButton tabIndex={-1} />
            <CarouselProgressLabel />
          </FlexLayout>
          <CarouselSlides>
            {sliderData.map((slide, index) => {
              const tabId = `${carouselId}-tab${index}`;
              return (
                <CarouselCard
                  className={styles.carouselSlide}
                  key={tabId}
                  aria-labelledby={`${tabId}-title`}
                  appearance="bordered"
                  media={
                    <img
                      aria-hidden={true}
                      alt=""
                      className={styles.carouselImage}
                      src={slide.image}
                    />
                  }
                  header={<H3 id={`${tabId}-title`}>{slide.title}</H3>}
                >
                  <Text>{slide.content}</Text>
                </CarouselCard>
              );
            })}
          </CarouselSlides>
        </StackLayout>
      </Carousel>
    </>
  );
};

