          console.log(`Number changed to ${newValue}`);
        }}
        value={value}
        startAdornment={
          <Button
            aria-hidden
            tabIndex={-1}
            onClick={() => {
              const newValue = Number.parseFloat(value);
              if (!Number.isNaN(newValue)) {
                const validValue = Math.max(
                  Number.MIN_SAFE_INTEGER,
                  Math.min(Number.MAX_SAFE_INTEGER, newValue - 1),
