                setValue(String(validValue));
              }
            }}
          >
            <RemoveIcon aria-hidden />
          </Button>
        }
        endAdornment={
          <Button
            aria-hidden
            tabIndex={-1}
            onClick={() => {
              const newValue = Number.parseFloat(value);
