                const validValue = Math.max(
                  Number.MIN_SAFE_INTEGER,
                  Math.min(Number.MAX_SAFE_INTEGER, newValue + 1),
                );
                setValue(String(validValue));
              }
            }}
          >
            <AddIcon aria-hidden />
          </Button>
        }
      />
      <FormFieldHelperText>Please enter a value</FormFieldHelperText>
    </FormField>
  );
};

