import {
  Button,
  Tab,
  TabBar,
  TabList,
  Tabs,
  TabTrigger,
  useAriaAnnouncer,
} from "@salt-ds/core";
import { AddIcon } from "@salt-ds/icons";
import { type ReactElement, useRef, useState } from "react";

export const AddANewTab = (): ReactElement => {
  const [tabs, setTabs] = useState(["Home", "Transactions", "Loans"]);
  const [value, setValue] = useState(tabs[0]);
  const newCount = useRef(0);
  const { announce } = useAriaAnnouncer();

  return (
    <div style={{ width: "100%", minWidth: 0 }}>
      <Tabs value={value} onChange={(_event, newValue) => setValue(newValue)}>
        <TabBar inset divider>
          <TabList aria-label="Example tablist">
            {tabs.map((label) => (
              <Tab value={label} key={label}>
                <TabTrigger>{label}</TabTrigger>
              </Tab>
            ))}
          </TabList>
          <Button
            aria-label="Add tab"
            appearance="transparent"
            onClick={() => {
              const newTab = `New tab${newCount.current > 0 ? ` ${newCount.current}` : ""}`;
              newCount.current += 1;

              setTabs((old) => old.concat(newTab));
              setValue(newTab);
              announce(`${newTab} tab added`, 150);
            }}
          >
            <AddIcon aria-hidden />
          </Button>
        </TabBar>
      </Tabs>
    </div>
  );
};

import {
  Tab,
  TabAction,
  TabBar,
  TabList,
  Tabs,
  TabTrigger,
  useAriaAnnouncer,
} from "@salt-ds/core";
import { CloseIcon } from "@salt-ds/icons";
import { type ReactElement, useState } from "react";

export const DismissibleTabs = (): ReactElement => {
  const [tabs, setTabs] = useState([
    "Home",
    "Transactions",
    "Loans",
    "Checks",
    "Liquidity",
  ]);

  const { announce } = useAriaAnnouncer();

  const handleDismissTab = (value: string) => {
    setTabs((oldTabs) => oldTabs.filter((tab) => tab !== value));
    announce(`${value} tab has been removed`, 150);
  };

  return (
    <div style={{ width: "100%", minWidth: 0 }}>
      <Tabs defaultValue={tabs[0]}>
        <TabBar inset divider>
          <TabList aria-label="Example tablist">
            {tabs.map((label) => (
              <Tab value={label} key={label}>
                <TabTrigger
                  onKeyDown={(event) => {
                    if (event.key === "Delete" && tabs.length > 1) {
                      handleDismissTab(label);
                    }
                  }}
                >
                  {label}
                </TabTrigger>
                {tabs.length > 1 && (
                  <TabAction
                    onClick={() => {
                      handleDismissTab(label);
                    }}
                    aria-label="Dismiss tab"
                  >
                    <CloseIcon aria-hidden />
                  </TabAction>
                )}
              </Tab>
            ))}
          </TabList>
        </TabBar>
      </Tabs>
    </div>
  );
};

